// Flip x or y
.flip-x {-webkit-transform: scaleX(-1);transform: scaleX(-1);}
.flip-y {-webkit-transform: scaleY(-1);transform: scaleY(-1);}

// Rotate
.rotate-45 {transform: rotate(45deg);}
.rotate-m45 {transform: rotate(-45deg);}
.rotate-90 {transform: rotate(90deg);}
.rotate-m90 {transform: rotate(-90deg);}
.rotate-180 {transform: rotate(180deg);}

// Shadow
.box-shadow {
    box-shadow: 0 0 .3rem .3rem _colour(box-shadow);
    -webkit-box-shadow: 0 0 .3rem .3rem _colour(box-shadow);
    -moz-box-shadow: 0 0 .3rem .3rem _colour(box-shadow);
}

.box-shadow-light {
    box-shadow: 0 0 .3rem .3rem _colour(box-shadow-light);
    -webkit-box-shadow: 0 0 .3rem .3rem _colour(box-shadow-light);
    -moz-box-shadow: 0 0 .3rem .3rem _colour(box-shadow-light);
}

.box-shadow-strong {
    box-shadow: 0 0 .3rem .3rem _colour(box-shadow-strong);
    -webkit-box-shadow: 0 0 .3rem .3rem _colour(box-shadow-strong);
    -moz-box-shadow: 0 0 .3rem .3rem _colour(box-shadow-strong);
}

// Z-index
.z-index-0 {z-index: 0!important;}
.z-index-1 {z-index: 1!important;}
.z-index-10 {z-index: 10!important;}
.z-index-100 {z-index: 100!important;}
.z-index-1000 {z-index: 1000!important;}
.z-index-10000 {z-index: 10000!important;}

// Cursors
.cursor-pointer {cursor: pointer!important;;}
.cursor-default {cursor: default!important;;}
.cursor-move {cursor: move!important;;}
.cursor-grab {cursor:grab!important;}
.cursor-grabbing {cursor:grabbing!important;}
.cursor-help {cursor:help!important;}
.cursor-crosshair {cursor:crosshair!important;}
.cursor-copy {cursor:copy!important;}
.cursor-progress {cursor:progress!important;}